import{_ as d,o as r,c as a,a2 as i}from"./chunks/framework.CqpfiAoK.js";const I=JSON.parse('{"title":"Обращение с четырьмя ветвями тёмных замещающих сущностей","description":"","frontmatter":{},"headers":[],"relativePath":"ru/59-黑暗置换体四类分支处置.md","filePath":"ru/59-黑暗置换体四类分支处置.md","lastUpdated":null}'),l={name:"ru/59-黑暗置换体四类分支处置.md"};function e(h,t,o,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="обращение-с-четырьмя-ветвями-темных-замещающих-сущностеи" tabindex="-1">Обращение с четырьмя ветвями тёмных замещающих сущностей <a class="header-anchor" href="#обращение-с-четырьмя-ветвями-темных-замещающих-сущностеи" aria-label="Permalink to &quot;Обращение с четырьмя ветвями тёмных замещающих сущностей&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>59</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Слияние и симбиоз, разделение и размещение, запечатывание и наблюдение, растворение, обращение по ветвям</td></tr></tbody></table><h2 id="i-общая-структура-обращения-по-ветвям" tabindex="-1">I. Общая структура обращения по ветвям <a class="header-anchor" href="#i-общая-структура-обращения-по-ветвям" aria-label="Permalink to &quot;I. Общая структура обращения по ветвям&quot;">​</a></h2><p>Обращение с тёмными замещающими сущностями — самая сложная область управления жизнью в Симбиотической Цивилизации Якоря. В отличие от процессов обращения в три типа для аномальной жизни и аномальной энергии, тёмные замещающие сущности из-за своей особой структуры сосуществования двух душ (см. <em>57-黑暗置换体起源与本质</em>) требуют более детализированных планов обращения по ветвям. Согласно этическим принципам, установленным в <em>58-双魂伦理准则</em>, с учётом стадии развития тёмной замещающей сущности, состояния исходной хозяйской души, характеристик тёмной души и уровня риска, обращение с тёмными замещающими сущностями делится на четыре ветви: тип слияния и симбиоза, тип разделения и размещения, тип запечатывания и наблюдения и тип растворения.</p><p>Выбор четырёх ветвей обращения следует следующей логике принятия решений:</p><table tabindex="0"><thead><tr><th>Фактор решения</th><th>Пункты рассмотрения</th></tr></thead><tbody><tr><td>Стадия развития</td><td>С первой по третью стадию приоритет спасению ; четвёртая стадия оценивается осторожно ; на пятой стадии исходный хозяин погиб</td></tr><tr><td>Состояние исходной хозяйской души</td><td>Существует ли исходная хозяйская душа, может ли она выразить свою волю, есть ли возможность восстановления</td></tr><tr><td>Характеристики тёмной души</td><td>Есть ли у тёмной души потенциал общения, есть ли пространство для перевоспитания, степень разрушительности</td></tr><tr><td>Уровень риска</td><td>Степень угрозы общественной безопасности и правам и интересам других</td></tr><tr><td>Заключение этической экспертизы</td><td>Мнение и решение Комитета этической экспертизы двойной души</td></tr><tr><td>Воля исходного хозяина</td><td>Выбор исходной хозяйской души, когда она может выразить свою волю</td></tr></tbody></table><h2 id="ii-первыи-тип-обращение-слияния-и-симбиоза" tabindex="-1">II. Первый тип: обращение слияния и симбиоза <a class="header-anchor" href="#ii-первыи-тип-обращение-слияния-и-симбиоза" aria-label="Permalink to &quot;II. Первый тип: обращение слияния и симбиоза&quot;">​</a></h2><p>Обращение слияния и симбиоза — самый позитивный и конструктивный вид обращения среди четырёх ветвей, применимо к тёмным замещающим сущностям, в которых исходная хозяйская душа и тёмная душа имеют возможность достичь примирения и осуществить слияние душ.</p><h3 id="i-условия-применения" tabindex="-1">(I) Условия применения <a class="header-anchor" href="#i-условия-применения" aria-label="Permalink to &quot;(I) Условия применения&quot;">​</a></h3><p>Обращение слияния и симбиоза должно одновременно удовлетворять следующим условиям:</p><ol><li>Тёмная замещающая сущность находится на третьей стадии (период формирования двух душ) или в начале четвёртой стадии (начало периода тёмного доминирования) ; исходная хозяйская душа ещё существует и обладает определённой степенью автономного сознания.</li><li>Исходная хозяйская душа ясно выражает волю попытаться слиться с тёмной душой, и эта воля признана подлинной и автономной.</li><li>Тёмная душа обладает определённой способностью к общению, проявляет не чисто разрушительные характеристики и имеет возможность принять слияние.</li><li>Уровень риска оценён как Второй уровень (средний риск) или ниже, и процесс слияния не будет представлять неконтролируемую угрозу общественной безопасности.</li><li>Одобрено экспертизой Комитета этической экспертизы двойной души.</li></ol><h3 id="ii-цель-обращения" tabindex="-1">(II) Цель обращения <a class="header-anchor" href="#ii-цель-обращения" aria-label="Permalink to &quot;(II) Цель обращения&quot;">​</a></h3><p>Путём направления исходной хозяйской души и тёмной души к примирению осуществить органическое слияние двух душ, формируя новую душу, обладающую и воспоминаниями, и личностью исходного хозяина, и тёмной силой. Слитая новая душа сохраняет гражданство и законные права исходного хозяина, получая при этом способность управлять тёмной энергией, становясь особым членом симбиотической цивилизации.</p><h3 id="iii-этапы-обращения" tabindex="-1">(III) Этапы обращения <a class="header-anchor" href="#iii-этапы-обращения" aria-label="Permalink to &quot;(III) Этапы обращения&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Этап</th><th>Название</th><th>Конкретное содержание</th><th>Ответственная организация</th></tr></thead><tbody><tr><td>Первый этап</td><td>Этическая экспертиза</td><td>Комитет этической экспертизы двойной души проводит всестороннюю экспертизу плана слияния, подтверждая соответствие этическим принципам</td><td>Комитет этической экспертизы двойной души</td></tr><tr><td>Второй этап</td><td>Коммуникационное сопровождение</td><td>В контролируемой среде профессиональные наставники душ помогают исходной хозяйской душе и тёмной душе общаться, способствуя взаимопониманию</td><td>Центр лечения душ + культиваторы</td></tr><tr><td>Третий этап</td><td>Переговоры о примирении</td><td>Направить две души к заключению соглашения о примирении по поводу слитой идентичности, воспоминаний, способностей, норм поведения и т.д.</td><td>Центр лечения душ + юридические советники</td></tr><tr><td>Четвёртый этап</td><td>Подготовка к слиянию</td><td>Провести подготовительные работы перед слиянием, такие как подготовка тела, балансировка энергии и психологическое строительство</td><td>Медицинская команда + инструкторы культивации</td></tr><tr><td>Пятый этап</td><td>Слияние душ</td><td>При совместном содействии продвинутых культиваторов и терапевтов душ осуществить операцию/ритуал слияния душ</td><td>Продвинутые культиваторы + терапевты душ</td></tr><tr><td>Шестой этап</td><td>Стабилизация после слияния</td><td>Провести стабилизационное лечение слитой новой души, отслеживая целостность души и адаптивность тела</td><td>Медицинская команда + группа наблюдения</td></tr><tr><td>Седьмой этап</td><td>Подтверждение идентичности</td><td>Подтвердить идентичность слитой новой души, сохранить гражданство исходного хозяина и обновить архив идентичности</td><td>Орган регистрации жительства + Бюро управления жизнью</td></tr><tr><td>Восьмой этап</td><td>Содействие интеграции</td><td>Предоставить слитому индивиду вспомогательные услуги, такие как психологическое консультирование, руководство культивацией и социальная интеграция</td><td>Департамент по делам Десяти Тысяч Рас + община</td></tr><tr><td>Девятый этап</td><td>Долгосрочное отслеживание</td><td>Проводить долгосрочное отслеживание и мониторинг слитого индивида не менее пяти лет, оценивая стабильность слияния и социальную адаптивность</td><td>Бюро управления жизнью + община</td></tr></tbody></table><h3 id="iv-управление-после-слияния" tabindex="-1">(IV) Управление после слияния <a class="header-anchor" href="#iv-управление-после-слияния" aria-label="Permalink to &quot;(IV) Управление после слияния&quot;">​</a></h3><p>Хотя слитый индивид сохраняет гражданство исходного хозяина, он должен принимать особое управление:</p><ul><li><strong>Контроль энергии</strong> : использование тёмной энергии слитым индивидом строго контролируется ; требуются периодические энергетические проверки, и использование тёмной энергии в общественных местах запрещено.</li><li><strong>Наблюдение за поведением</strong> : слитый индивид должен периодически отчитываться о своём поведении в Бюро управления жизнью и принимать наблюдение и помощь общины.</li><li><strong>Ограничения культивации</strong> : слитый индивид не может культивировать техники, способные усилить тёмные атрибуты ; планы культивации должны быть одобрены.</li><li><strong>План экстренного реагирования</strong> : создать план экстренного реагирования на потерю контроля тёмной энергии у слитых индивидов ; при появлении признаков потери контроля немедленно активировать контроль.</li><li><strong>Механизм выхода</strong> : если после слияния появляется серьёзная нестабильность или устойчивое опасное поведение, может быть проведена переоценка и изменён тип обращения.</li></ul><h3 id="v-управление-неудачеи-слияния" tabindex="-1">(V) Управление неудачей слияния <a class="header-anchor" href="#v-управление-неудачеи-слияния" aria-label="Permalink to &quot;(V) Управление неудачей слияния&quot;">​</a></h3><p>Слияние душ сопряжено с риском неудачи ; планы управления неудачей слияния:</p><ul><li><strong>Прерывание слияния</strong> : если в процессе слияния возникает серьёзная нестабильность, немедленно прервать слияние и вернуть две души в состояние до слияния.</li><li><strong>Неполное слияние</strong> : если после слияния появляется неполнота души или расщепление личности, перейти к обращению разделения и размещения для последующей обработки.</li><li><strong>Потеря контроля слияния</strong> : если новая душа после слияния проявляет неконтролируемую разрушительность, немедленно перейти к обращению запечатывания и наблюдения или растворения.</li></ul><h2 id="iii-второи-тип-обращение-разделения-и-размещения" tabindex="-1">III. Второй тип: обращение разделения и размещения <a class="header-anchor" href="#iii-второи-тип-обращение-разделения-и-размещения" aria-label="Permalink to &quot;III. Второй тип: обращение разделения и размещения&quot;">​</a></h2><p>Обращение разделения и размещения применяется к тёмным замещающим сущностям, в которых исходная хозяйская душа и тёмная душа не могут слиться, но могут быть разделены ; посредством операции по разделению душ две души разделяются и размещаются соответственно.</p><h3 id="i-условия-применения-1" tabindex="-1">(I) Условия применения <a class="header-anchor" href="#i-условия-применения-1" aria-label="Permalink to &quot;(I) Условия применения&quot;">​</a></h3><ol><li>Тёмная замещающая сущность находится на третьей или четвёртой стадии ; исходная хозяйская душа ещё существует и имеет возможность восстановления.</li><li>Попытка слияния двух душ не удалась или отсутствуют условия для слияния.</li><li>Техническая оценка признаёт разделение душ осуществимым, и исходная хозяйская душа может выжить независимо после разделения.</li><li>Исходная хозяйская душа ясно выражает волю к разделению.</li><li>Одобрено экспертизой Комитета этической экспертизы двойной души.</li></ol><h3 id="ii-цель-обращения-1" tabindex="-1">(II) Цель обращения <a class="header-anchor" href="#ii-цель-обращения-1" aria-label="Permalink to &quot;(II) Цель обращения&quot;">​</a></h3><p>Посредством операции по разделению душ отделить исходную хозяйскую душу от тёмной души ; исходная хозяйская душа возвращается в тело и возобновляет нормальную жизнь, а тёмная душа помещается в специальный контейнер или учреждение для контроля и исследований.</p><h3 id="iii-этапы-обращения-1" tabindex="-1">(III) Этапы обращения <a class="header-anchor" href="#iii-этапы-обращения-1" aria-label="Permalink to &quot;(III) Этапы обращения&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Этап</th><th>Название</th><th>Конкретное содержание</th><th>Ответственная организация</th></tr></thead><tbody><tr><td>Первый этап</td><td>Этическая экспертиза</td><td>Комитет этической экспертизы двойной души проводит экспертизу плана разделения, подтверждая необходимость и осуществимость разделения</td><td>Комитет этической экспертизы двойной души</td></tr><tr><td>Второй этап</td><td>Подготовка к разделению</td><td>Провести подготовительные работы перед разделением, такие как оценка тела, проверка состояния души и регулировка энергетического баланса</td><td>Медицинская команда + терапевты душ</td></tr><tr><td>Третий этап</td><td>Разделение душ</td><td>При содействии продвинутых культиваторов и терапевтов душ осуществить операцию по разделению душ, отделив две души от тела</td><td>Продвинутые культиваторы + терапевты душ</td></tr><tr><td>Четвёртый этап</td><td>Возвращение исходного хозяина</td><td>Заново имплантировать исходную хозяйскую душу в тело, проводя стабилизацию души и реабилитацию тела</td><td>Медицинская команда</td></tr><tr><td>Пятый этап</td><td>Размещение тёмной души</td><td>Поместить отделённую тёмную душу в специальный контейнер контейнмента души и хранить её в учреждении запечатывания душ</td><td>Бюро управления жизнью + техническая команда</td></tr><tr><td>Шестой этап</td><td>Восстановление исходного хозяина</td><td>Провести всестороннюю физическую реабилитацию, психологическое лечение и восстановление культивации для исходного хозяина, помогая ему вернуться к нормальной жизни</td><td>Медицинская команда + психологические консультанты</td></tr><tr><td>Седьмой этап</td><td>Восстановление идентичности</td><td>Подтвердить полное восстановление идентичности и прав исходного хозяина и обновить архив идентичности</td><td>Орган регистрации жительства</td></tr><tr><td>Восьмой этап</td><td>Управление тёмной душой</td><td>Проводить непрерывный мониторинг и исследования отделённой тёмной души, изучая возможность её перевоспитания или растворения</td><td>Бюро управления жизнью + научно-исследовательская организация</td></tr></tbody></table><h3 id="iv-размещение-отделеннои-темнои-души" tabindex="-1">(IV) Размещение отделённой тёмной души <a class="header-anchor" href="#iv-размещение-отделеннои-темнои-души" aria-label="Permalink to &quot;(IV) Размещение отделённой тёмной души&quot;">​</a></h3><p>Отделённая тёмная душа размещается следующим образом:</p><ul><li><strong>Контейнер души</strong> : тёмная душа помещается в специальный контейнер контейнмента души, оснащённый такими устройствами, как энергетическое экранирование, подавление сознания и безопасная блокировка.</li><li><strong>Учреждение запечатывания</strong> : контейнер хранится в специальном учреждении запечатывания душ, которое осуществляет высочайший уровень управления безопасностью.</li><li><strong>Непрерывный мониторинг</strong> : проводить круглосуточный непрерывный мониторинг сознательной активности и энергетических колебаний тёмной души.</li><li><strong>Исследование и использование</strong> : под строгой этической экспертизой могут проводиться научные исследования тёмной души, изучающие сущность Бездонной Энергии и методы очищения.</li><li><strong>Окончательное обращение</strong> : согласно результатам исследований и оценке рисков принять окончательное решение об обращении с тёмной душой — перевоспитание в неразрушительное существование, долгосрочное запечатывание или очищение и растворение.</li></ul><h3 id="v-риски-разделения-и-меры-реагирования" tabindex="-1">(V) Риски разделения и меры реагирования <a class="header-anchor" href="#v-риски-разделения-и-меры-реагирования" aria-label="Permalink to &quot;(V) Риски разделения и меры реагирования&quot;">​</a></h3><p>Операция по разделению душ сопряжена со следующими рисками, для которых должны быть разработаны планы реагирования:</p><table tabindex="0"><thead><tr><th>Риск</th><th>План реагирования</th></tr></thead><tbody><tr><td>Исходная хозяйская душа повреждается в процессе разделения</td><td>Укрепить душу перед разделением ; продвинутые культиваторы обеспечивают полную защиту во время разделения</td></tr><tr><td>Тело исходного хозяина не может адаптироваться после разделения</td><td>Провести всестороннюю физическую реабилитацию и стабилизационное лечение души после разделения</td></tr><tr><td>Тёмная душа сбегает в процессе разделения</td><td>Разделение проводится в учреждении высочайшего уровня безопасности, оснащённом множественными устройствами контейнмента</td></tr><tr><td>Неполное разделение, остаточная тёмная энергия</td><td>Провести глубокое очищающее лечение после разделения для устранения остаточной тёмной энергии</td></tr><tr><td>Психологическая травма исходной хозяйской души после разделения</td><td>Обеспечить долгосрочное психологическое консультирование и психиатрическое лечение</td></tr></tbody></table><h2 id="iv-третии-тип-обращение-запечатывания-и-наблюдения" tabindex="-1">IV. Третий тип: обращение запечатывания и наблюдения <a class="header-anchor" href="#iv-третии-тип-обращение-запечатывания-и-наблюдения" aria-label="Permalink to &quot;IV. Третий тип: обращение запечатывания и наблюдения&quot;">​</a></h2><p>Обращение запечатывания и наблюдения применяется к тёмным замещающим сущностям, которые не могут ни слиться, ни быть разделены, но чья исходная хозяйская душа ещё существует и которые не имеют условий для немедленного растворения ; посредством запечатывания их опасность контролируется, с долгосрочным наблюдением и непрерывной оценкой.</p><h3 id="i-условия-применения-2" tabindex="-1">(I) Условия применения <a class="header-anchor" href="#i-условия-применения-2" aria-label="Permalink to &quot;(I) Условия применения&quot;">​</a></h3><ol><li>Тёмная замещающая сущность находится на четвёртой стадии (период тёмного доминирования) ; исходная хозяйская душа глубоко подавлена, но ещё не погибла.</li><li>И слияние, и разделение лишены технической осуществимости или их риски слишком высоки.</li><li>Уровень риска тёмной замещающей сущности — Третий уровень (высокий риск), но ещё не достиг степени, требующей немедленного растворения.</li><li>Исходная хозяйская душа всё ещё имеет слабую надежду на восстановление, требуя времени и условий для ожидания поворотного момента.</li><li>Комитет этической экспертизы двойной души проводит экспертизу и одобряет план запечатывания.</li></ol><h3 id="ii-цель-обращения-2" tabindex="-1">(II) Цель обращения <a class="header-anchor" href="#ii-цель-обращения-2" aria-label="Permalink to &quot;(II) Цель обращения&quot;">​</a></h3><p>Посредством запечатывания подавить силу и активность тёмной души, контролировать опасность тёмной замещающей сущности, одновременно защищая исходную хозяйскую душу от полного уничтожения, ожидая в долгосрочном наблюдении созревания возможностей для восстановления или обращения.</p><h3 id="iii-способы-запечатывания" tabindex="-1">(III) Способы запечатывания <a class="header-anchor" href="#iii-способы-запечатывания" aria-label="Permalink to &quot;(III) Способы запечатывания&quot;">​</a></h3><p>Согласно уровню силы и характеристикам тёмной замещающей сущности выбрать следующие способы запечатывания:</p><table tabindex="0"><thead><tr><th>Способ запечатывания</th><th>Принцип</th><th>Применимые объекты</th></tr></thead><tbody><tr><td>Энергетическое запечатывание</td><td>Использовать запечатывающие массивы или устройства для подавления потока и выхода тёмной энергии</td><td>Тёмные замещающие сущности низкого и среднего уровня силы</td></tr><tr><td>Пространственное запечатывание</td><td>Запечатать тёмную замещающую сущность в независимом изолированном пространстве, разорвав связь с внешним миром</td><td>Тёмные замещающие сущности высокого уровня силы или с инфекционностью</td></tr><tr><td>Запечатывание сознания</td><td>Подавить сознательную активность тёмной души, приведя её в спящее или полуспящее состояние</td><td>Тёмные замещающие сущности с активным сознанием и способностью атаки души</td></tr><tr><td>Множественное запечатывание</td><td>Одновременно использовать несколько способов запечатывания, образуя множественную защиту</td><td>Тёмные замещающие сущности чрезвычайно высокого уровня силы или с несколькими опасными характеристиками</td></tr><tr><td>Запечатывание Якоря</td><td>Использовать изначальные атрибуты энергии Якоря для запечатывания, самый мощный способ запечатывания</td><td>Тёмные замещающие сущности, опасные на космическом уровне</td></tr></tbody></table><h3 id="iv-этапы-обращения" tabindex="-1">(IV) Этапы обращения <a class="header-anchor" href="#iv-этапы-обращения" aria-label="Permalink to &quot;(IV) Этапы обращения&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Этап</th><th>Название</th><th>Конкретное содержание</th><th>Ответственная организация</th></tr></thead><tbody><tr><td>Первый этап</td><td>Этическая экспертиза</td><td>Комитет этической экспертизы двойной души проводит экспертизу плана запечатывания, подтверждая необходимость и уместность запечатывания</td><td>Комитет этической экспертизы двойной души</td></tr><tr><td>Второй этап</td><td>Подготовка к запечатыванию</td><td>Подготовить запечатывающий массив/устройство/пространство, выделив энергию и персонал, необходимые для запечатывания</td><td>Техническая команда + продвинутые культиваторы</td></tr><tr><td>Третий этап</td><td>Подавление и контроль</td><td>При содействии службы безопасности подавить тёмную замещающую сущность, обеспечив отсутствие происшествий в процессе запечатывания</td><td>Департамент безопасности + продвинутые культиваторы</td></tr><tr><td>Четвёртый этап</td><td>Осуществление запечатывания</td><td>Осуществить запечатывание согласно плану, подавив силу и активность тёмной души</td><td>Продвинутые культиваторы + запечатыватели</td></tr><tr><td>Пятый этап</td><td>Проверка запечатывания</td><td>Проверить эффективность и стабильность запечатывания, подтвердив, что опасность тёмной замещающей сущности контролируется</td><td>Техническая команда + группа наблюдения</td></tr><tr><td>Шестой этап</td><td>Перемещение и размещение</td><td>Переместить запечатанную тёмную замещающую сущность в специальное учреждение запечатывания и наблюдения</td><td>Департамент безопасности + Бюро управления жизнью</td></tr><tr><td>Седьмой этап</td><td>Непрерывное наблюдение</td><td>Проводить круглосуточное непрерывное наблюдение за состоянием запечатывания, периодически проверяя стабильность запечатывания</td><td>Группа наблюдения</td></tr><tr><td>Восьмой этап</td><td>Периодическая переоценка</td><td>Проводить всестороннюю переоценку каждые шесть месяцев, оценивая состояние исходной хозяйской души, характеристики тёмной души и стабильность запечатывания, определяя возможность корректировки типа обращения</td><td>Группа экспертов по идентификации + Комитет этической экспертизы</td></tr><tr><td>Девятый этап</td><td>Обслуживание запечатывания</td><td>Периодически обслуживать и укреплять запечатывание, предотвращая ослабление или повреждение</td><td>Запечатыватели + техническая команда</td></tr></tbody></table><h3 id="v-стандарты-учреждении-запечатывания-и-наблюдения" tabindex="-1">(V) Стандарты учреждений запечатывания и наблюдения <a class="header-anchor" href="#v-стандарты-учреждении-запечатывания-и-наблюдения" aria-label="Permalink to &quot;(V) Стандарты учреждений запечатывания и наблюдения&quot;">​</a></h3><ul><li><strong>Размещение</strong> : учреждения запечатывания и наблюдения размещаются в отдалённых районах со стабильной геологией, стабильной энергетической средой и редким населением, или в независимых изолированных плоскостях.</li><li><strong>Строительство</strong> : учреждения используют многослойные защитные конструкции, включая три уровня защиты: физические барьеры, энергетические барьеры и пространственную блокировку.</li><li><strong>Оборудование</strong> : оснащены высокоточными устройствами наблюдения за запечатыванием, автоматическими системами укрепления, системами экстренного реагирования и резервными энергосистемами.</li><li><strong>Персонал</strong> : действует круглосуточная система дежурства, с запечатывателями, наблюдателями, сотрудниками безопасности и персоналом экстренного реагирования.</li><li><strong>Экстренные ситуации</strong> : разработаны различные планы экстренного реагирования на повреждение запечатывания, побег тёмной души, гибель исходной хозяйской души и т.д., с регулярными учениями.</li></ul><h3 id="vi-снятие-и-преобразование-запечатывания" tabindex="-1">(VI) Снятие и преобразование запечатывания <a class="header-anchor" href="#vi-снятие-и-преобразование-запечатывания" aria-label="Permalink to &quot;(VI) Снятие и преобразование запечатывания&quot;">​</a></h3><p>В следующих обстоятельствах запечатывание может быть снято или тип обращения изменён:</p><ul><li><strong>Восстановление исходного хозяина</strong> : если исходная хозяйская душа постепенно восстанавливается в период запечатывания и обладает условиями для разделения или слияния, запечатывание может быть снято и обращение переведено в тип разделения и размещения или слияния и симбиоза.</li><li><strong>Перевоспитание тёмной души</strong> : если тёмная душа в период запечатывания проявляет потенциал перевоспитания, запечатывание может быть снято в контролируемых условиях для попыток перевоспитания.</li><li><strong>Неудача запечатывания</strong> : если запечатывание получает непоправимое повреждение или ослабление, а опасность тёмной замещающей сущности неконтролируема, она может быть переведена в тип растворения.</li><li><strong>Гибель исходного хозяина</strong> : если исходная хозяйская душа полностью погибает в период запечатывания и тёмная замещающая сущность становится чисто тёмным существованием, она может быть переведена в тип растворения или продолжать запечатывание в зависимости от её опасности.</li></ul><h2 id="v-четвертыи-тип-обращение-растворения" tabindex="-1">V. Четвёртый тип: обращение растворения <a class="header-anchor" href="#v-четвертыи-тип-обращение-растворения" aria-label="Permalink to &quot;V. Четвёртый тип: обращение растворения&quot;">​</a></h2><p>Обращение растворения — самый суровый вид обращения среди четырёх ветвей, применяется к тёмным замещающим сущностям, которые невозможно спасти и которые чрезвычайно опасны ; посредством уничтожения тёмной души (и при необходимости уничтожения всего тела) угроза устраняется.</p><h3 id="i-условия-применения-3" tabindex="-1">(I) Условия применения <a class="header-anchor" href="#i-условия-применения-3" aria-label="Permalink to &quot;(I) Условия применения&quot;">​</a></h3><p>Обращение растворения применяется в следующих ситуациях:</p><ol><li>Тёмная замещающая сущность находится на пятой стадии (период полного замещения) ; исходная хозяйская душа полностью погибла, тело полностью контролируется тёмной душой, став чисто тёмным существованием.</li><li>Тёмная замещающая сущность находится на четвёртой стадии ; исходная хозяйская душа ещё существует, но не может восстановиться, слияние, разделение и запечатывание невозможны, а её опасность продолжает нарастать.</li><li>Уровень риска тёмной замещающей сущности — Четвёртый уровень (чрезвычайно высокий риск), с разрушительной силой космического уровня, напрямую угрожающей выживанию цивилизации, а другие способы обращения не могут контролировать её угрозу.</li><li>При обращении запечатывания и наблюдения запечатывание не удалось и не может быть применено заново, а опасность тёмной замещающей сущности неконтролируема.</li><li>Комитет этической экспертизы двойной души проводит экспертизу и одобряет план растворения (при чрезвычайно высоком риске допускается сначала обращение, затем оформление задним числом).</li></ol><h3 id="ii-принципы-растворения" tabindex="-1">(II) Принципы растворения <a class="header-anchor" href="#ii-принципы-растворения" aria-label="Permalink to &quot;(II) Принципы растворения&quot;">​</a></h3><p>Обращение растворения связано с уничтожением жизни и должно строго следовать следующим принципам:</p><ul><li><strong>Принцип последнего средства</strong> : растворение должно быть последним средством, когда все другие способы обращения невозможны.</li><li><strong>Принцип пропорциональности</strong> : интенсивность растворения должна соответствовать степени угрозы ; чрезмерное применение силы запрещено.</li><li><strong>Принцип минимальных страданий</strong> : растворение должно по возможности применять безболезненные и быстрые способы, уменьшая страдания тёмной души (и исходной хозяйской души, если она ещё существует).</li><li><strong>Принцип уважения исходного хозяина</strong> : если исходная хозяйская душа ещё существует, перед растворением её следует по возможности сохранять в ясном сознании и достоинстве ; при необходимости дать исходному хозяину попрощаться с родными и друзьями.</li><li><strong>Принцип полной записи</strong> : процесс растворения полностью записывается, формируя полный архив для экспертизы и прослеживаемости.</li><li><strong>Принцип последующей экспертизы</strong> : после завершения растворения проводится последующая экспертиза, оценивающая необходимость и уместность растворения и обобщающая уроки.</li></ul><h3 id="iii-способы-растворения" tabindex="-1">(III) Способы растворения <a class="header-anchor" href="#iii-способы-растворения" aria-label="Permalink to &quot;(III) Способы растворения&quot;">​</a></h3><p>Согласно уровню силы и характеристикам тёмной замещающей сущности выбрать следующие способы растворения:</p><table tabindex="0"><thead><tr><th>Способ растворения</th><th>Принцип</th><th>Применимые объекты</th></tr></thead><tbody><tr><td>Растворение Очищением Святым Светом</td><td>Использовать энергию Святого Света высокой интенсивности для очищения тёмной души, заставляя её рассеяться в свете</td><td>Тёмные замещающие сущности низкого и среднего уровня силы</td></tr><tr><td>Искусство Аннигиляции Души</td><td>Напрямую атаковать и аннигилировать ядро тёмной души, вызывая её полную гибель</td><td>Тёмные замещающие сущности высокого уровня силы</td></tr><tr><td>Растворение Пространственным Изгнанием</td><td>Изгнать тёмную замещающую сущность в пространство небытия или конец времён, заставив её раствориться в пространственно-временном распаде</td><td>Тёмные замещающие сущности с сильной физической защитой</td></tr><tr><td>Растворение Изначальем Якоря</td><td>Призвать изначальную энергию Якоря, разложив тёмную замещающую сущность и вернув её к изначалью вселенной</td><td>Тёмные замещающие сущности, опасные на космическом уровне</td></tr><tr><td>Совместное Растворение Сил Множества Плоскостей</td><td>Несколько Верховных Силачей Плоскости объединяют усилия, используя абсолютную силу для подавления и уничтожения тёмной замещающей сущности</td><td>Тёмные замещающие сущности чрезвычайно высокого уровня силы</td></tr><tr><td>Растворение Индуцированным Самоподрывом</td><td>Под строгим контролем индуцировать самоподрыв тёмной энергии тёмной замещающей сущности, растворив её в энергетическом взрыве</td><td>Тёмные замещающие сущности с нестабильной энергией</td></tr></tbody></table><h3 id="iv-этапы-обращения-1" tabindex="-1">(IV) Этапы обращения <a class="header-anchor" href="#iv-этапы-обращения-1" aria-label="Permalink to &quot;(IV) Этапы обращения&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Этап</th><th>Название</th><th>Конкретное содержание</th><th>Ответственная организация</th></tr></thead><tbody><tr><td>Первый этап</td><td>Этическая экспертиза/экстренное одобрение</td><td>В обычных обстоятельствах экспертиза и одобрение Комитетом этической экспертизы двойной души ; при чрезвычайно высоком риске приказ самого высокого по должности руководителя на месте, с оформлением задним числом</td><td>Комитет этической экспертизы двойной души / самый высокий по должности руководитель на месте</td></tr><tr><td>Второй этап</td><td>Разработка плана</td><td>Разработать детальный план растворения, включая способы растворения, распределение сил, меры безопасности, планы экстренного реагирования и оценку воздействия на окружающую среду</td><td>Боевой командный штаб + техническая группа экспертов</td></tr><tr><td>Третий этап</td><td>Сбор сил</td><td>Собрать культиваторов, технический персонал, оборудование и энергетические ресурсы, необходимые для растворения</td><td>Департамент безопасности + продвинутые культиваторы</td></tr><tr><td>Четвёртый этап</td><td>Блокировка зоны</td><td>Блокировать зону растворения, эвакуировать окружающий персонал и установить линии безопасности</td><td>Департамент безопасности + местное правительство</td></tr><tr><td>Пятый этап</td><td>Подавление и контроль</td><td>Сначала силой подавления контролировать действия тёмной замещающей сущности, предотвращая её побег или большее разрушение</td><td>Продвинутые культиваторы + силы безопасности</td></tr><tr><td>Шестой этап</td><td>Осуществление растворения</td><td>Осуществить растворение согласно плану, с всесторонним мониторингом процесса ; при любой аномалии немедленно активировать план экстренного реагирования</td><td>Продвинутые культиваторы + техническая команда</td></tr><tr><td>Седьмой этап</td><td>Подтверждение гибели</td><td>Подтвердить, что тёмная душа (и тело) полностью погибла, проверив наличие остаточной энергии или фрагментов души</td><td>Группа наблюдения + группа экспертов</td></tr><tr><td>Восьмой этап</td><td>Восстановление окружающей среды</td><td>Провести восстановление окружающей среды зоны растворения, устранив остаточную тёмную энергию и восстановив экологический баланс</td><td>Департамент экологии и окружающей среды</td></tr><tr><td>Девятый этап</td><td>Урегулирование последствий</td><td>Уведомить родных и друзей исходного хозяина (если исходный хозяин погиб), урегулировать наследство исходного хозяина и провести психологическое консультирование</td><td>Департамент гражданских дел + психологические консультанты</td></tr><tr><td>Десятый этап</td><td>Архивация и последующая экспертиза</td><td>Заархивировать полные записи процесса растворения и провести последующую экспертизу, оценивая необходимость и уместность</td><td>Бюро управления жизнью + Комитет этической экспертизы</td></tr></tbody></table><h3 id="v-процедура-экстренного-растворения" tabindex="-1">(V) Процедура экстренного растворения <a class="header-anchor" href="#v-процедура-экстренного-растворения" aria-label="Permalink to &quot;(V) Процедура экстренного растворения&quot;">​</a></h3><p>Для тёмных замещающих сущностей Четвёртого уровня (чрезвычайно высокий риск), напрямую угрожающих выживанию цивилизации, применяется процедура экстренного растворения:</p><ol><li>Самый высокий по должности руководитель на месте может непосредственно приказать начать экстренное растворение без предварительной этической экспертизы, но обязан в течение 24 часов после растворения доложить в Комитет этической экспертизы двойной души для регистрации.</li><li>Экстренное растворение может задействовать высочайший уровень силы и энергетических ресурсов цивилизации, включая централизованный вызов энергии Якоря и совместные действия множества Верховных Силачей Плоскости.</li><li>Приоритетная цель экстренного растворения — устранить угрозу и защитить жизнь и безопасность цивилизации, а не добиваться «элегантности» или «безболезненности» способа растворения (но сопутствующий вред всё же следует минимизировать по возможности).</li><li>После экстренного растворения следует провести всестороннюю экологическую оценку и восстановление, предотвратив остаточную тёмную энергию и вторичные катастрофы.</li><li>Случаи экстренного растворения должны подвергаться последующему разбору и глубокому анализу, с обобщением уроков и совершенствованием механизмов предупреждения и обращения.</li></ol><h2 id="vi-механизм-преобразования-четырех-ветвеи-обращения" tabindex="-1">VI. Механизм преобразования четырёх ветвей обращения <a class="header-anchor" href="#vi-механизм-преобразования-четырех-ветвеи-обращения" aria-label="Permalink to &quot;VI. Механизм преобразования четырёх ветвей обращения&quot;">​</a></h2><p>Обращение с тёмными замещающими сущностями не является неизменным ; согласно изменениям ситуации в процессе обращения возможен переход между четырьмя ветвями:</p><table tabindex="0"><thead><tr><th>Направление преобразования</th><th>Условия преобразования</th><th>Процедура преобразования</th></tr></thead><tbody><tr><td>Слияние → Разделение</td><td>Попытка слияния не удалась или после слияния появилась серьёзная нестабильность</td><td>Переоценка ; после одобрения этической экспертизой перевести в разделение</td></tr><tr><td>Слияние → Запечатывание</td><td>Слияние не удалось, разделение невозможно, требуется контроль рисков</td><td>Переоценка ; после одобрения этической экспертизой перевести в запечатывание</td></tr><tr><td>Слияние → Растворение</td><td>Слияние вышло из-под контроля, новая душа обладает неконтролируемой разрушительностью</td><td>Экстренная оценка ; немедленно перевести в растворение</td></tr><tr><td>Разделение → Запечатывание</td><td>Разделение не удалось или исходный хозяин не может восстановиться после разделения, требуется контроль рисков</td><td>Переоценка ; после одобрения этической экспертизой перевести в запечатывание</td></tr><tr><td>Разделение → Растворение</td><td>Тёмная душа сбежала в процессе разделения и неконтролируема</td><td>Экстренная оценка ; немедленно перевести в растворение</td></tr><tr><td>Запечатывание → Слияние</td><td>В период запечатывания исходная хозяйская душа восстановилась и обладает условиями для слияния</td><td>Обнаружено при периодической переоценке ; после одобрения этической экспертизой перевести в слияние</td></tr><tr><td>Запечатывание → Разделение</td><td>В период запечатывания исходная хозяйская душа восстановилась и обладает условиями для разделения</td><td>Обнаружено при периодической переоценке ; после одобрения этической экспертизой перевести в разделение</td></tr><tr><td>Запечатывание → Растворение</td><td>Запечатывание не удалось и не может быть применено заново, опасность неконтролируема</td><td>Экстренная оценка ; немедленно перевести в растворение</td></tr><tr><td>Растворение → Другие</td><td>Растворение — последнее средство ; после применения необратимо</td><td>Не применимо</td></tr></tbody></table><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Обращение с четырьмя ветвями тёмных замещающих сущностей — вершина управления жизнью в Симбиотической Цивилизации Якоря. От активного спасения слиянием и симбиозом, через точное разделение и размещение, терпеливое ожидание запечатывания и наблюдения, до последнего средства растворения — четыре ветви образуют полный спектр обращения от самого мягкого до самого сурового, охватывая все возможные ситуации с тёмными замещающими сущностями. Эта система обращения одновременно отстаивает этическую линию «прилагать все усилия для спасения каждой души» и линию безопасности «решительно устранять неконтролируемые угрозы», воплощая изысканный баланс симбиотической цивилизации между жизненной этикой и управлением безопасностью.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Происхождение и сущность тёмных замещающих сущностей)</li><li>58-双魂伦理准则 (Этика Двойной Души)</li><li>54-奇特生命三类处置流程 (Процесс обращения с тремя типами аномальной жизни)</li><li>48-司法体系与裁决机制 (Судебная система и механизм решений)</li></ul>',74)])])}const c=d(l,[["render",e]]);export{I as __pageData,c as default};
